def eulerian_num(n, m):
    if m >= n or m < 0:
        return 0
    if m == n - 1 or m == 0:
        return 1

    # Create DP table
    dp = [[0] * n for _ in range(n)]

    # Base cases
    for i in range(n):
        dp[i][0] = 1  # A(n, 0) = 1

    for i in range(1, n):
        dp[i][i] = 1  # A(i+1, i) = 1

    # Fill the table using recurrence relation
    for i in range(1, n):
        for j in range(1, i+1):
            if j >= i+1:
                continue
            dp[i][j] = (i - j + 1) * dp[i-1][j-1] + (j + 1) * dp[i-1][j]

    return dp[n-1][m]

