def eulerian_num(n, m):
    # Base cases
    if n == 0 and m == 0:
        return 1
    if m == 0 or m == n - 1:
        return 1
    if m == n or m < 0:
        return 0

    # Recursion table
    # We use a recursive approach with memoization to avoid recomputation
    # To optimize, we compute top-down with memoization
    memo = {}

    def dp(x, y):
        if (x, y) in memo:
            return memo[(x, y)]
        if y == x - 1 or y == 0:
            memo[(x, y)] = 1
        elif y == x or x == 0 or y < 0:
            memo[(x, y)] = 0
        else:
            memo[(x, y)] = (x - y) * dp(x - 1, y - 1) + (y + 1) * dp(x - 1, y)

        return memo[(x, y)]

    return dp(n, m)

def eulerian_num(n, m):
    # Initialize a memo table to store computed values
    memo = [[0] * (n + 1) for _ in range(n + 1)]

    # Base cases
    for i in range(1, n + 1):
        memo[i][i - 1] = 1

    # Fill in the memo table using the recurrence:
    # A(n, m) = (n - m) * A(n - 1, m - 1) + (m + 1) * A(n - 1, m)
    for i in range(2, n + 1):
        for j in range(0, i):
            if j == i - 1:
                continue  # handled by initialization
            memo[i][j] = (i - j) * memo[i - 1][j - 1] + (j + 1) * memo[i - 1][j]

