def larg_nnum(list1, n):
    if n <= 0 or not list1:
        return []

    # Use a min-heap to keep track of the n largest elements.
    heap = []

    # Iterate over each element in the list
    for num in list1:
        # If the heap has fewer than n elements, add the number to the heap.
        if len(heap) < n:
            heapq.heappush(heap, num)
        # If the number is larger than the smallest element in the heap, replace it.
        elif num > heap[0]:
            heapq.heappop(heap)
            heapq.heappush(heap, num)

    return heap

