    for i in range(n):
        for j in range(n + 1):
            if dp[i][j] > 0:
                dp[i + 1][j] += dp[i][j]  # add 0
                if j + 1 <= n:
                    dp[i + 1][j + 1] += dp[i][j]  # add 1

    # We need to count pairs where sum of first n bits equals sum of last n bits
    # This is equivalent to the sum of dp[n][j]^2 for all possible sums j
    count = 0
    for j in range(n + 1):
        count += dp[n][j] ** 2

    return count

