import re

def find_adverb_position(text):
    # Regular expression to find words ending with 'ly' case-insensitively
    match = re.search(r'\b\w*ly\b', text.lower())
    if not match:
        return None  # No adverb found
    start_pos = match.start()
    end_pos = start_pos + len(match.group())
