def is_Sub_Array(A, B):
    # Check if B is a subsequence of A
    if not B:
        return True  # empty list is a subsequence of any list
    if not A:
        return False  # non-empty list cannot be a subsequence of empty list

    # Initialize pointers for A and B
    i = 0  # pointer for A
    j = 0  # pointer for B

    # Traverse both A and B
    while i < len(A) and j < len(B):
        if A[i] == B[j]:
            j += 1
        i += 1

    # If all elements in B have been matched, B is a subsequence of A
    return j == len(B)

