    # and their recurrence: Bell(n+1) = sum of Bell(j) * Stirling(remaining, n-j) for j from 0 to n
    # Here we use a dynamic programming approach
    bell = [[0] * (n + 1) for _ in range(n + 1)]
    stirling = [[0] * (n + 1) for _ in range(n + 1)]

