        for j in range(1, i + 1):
            stirling[i][j] = stirling[i-1][j-1] + j * stirling[i-1][j]

    bell[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            bell[i][j] = bell[i-1][j-1] + stirling[i][j-1]

    return sum(bell[n][j] for j in range(1, n + 1))

