        return 0.0

    n = len(cost)
    total = [[0.0] * n for _ in range(n)]
    count = [[0] * n for _ in range(n)]

    total[0][0] = cost[0][0]
    count[0][0] = 1

    for i in range(1, n):
        total[i][0] = total[i-1][0] + cost[i][0]
        count[i][0] = count[i-1][0] + 1

    for j in range(1, n):
