def maxAverageOfPath(cost):
    if not cost or not cost[0]:
        return 0.0

    n = len(cost)
    # Initialize DP tables: max_sum[i][j] = max sum to reach (i,j)
    # and path_length[i][j] = max steps (cells) in the path to (i,j)
    max_sum = [[0] * n for _ in range(n)]
    path_length = [[0] * n for _ in range(n)]

    # Base case: starting cell (0,0)
    max_sum[0][0] = cost[0][0]
    path_length[0][0] = 1

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue  # already initialized
            # Initialize with possible paths
            current_paths = []
            if i > 0:
                current_paths.append((max_sum[i-1][j], path_length[i-1][j]))
            if j > 0:
                current_paths.append((max_sum[i][j-1], path_length[i][j-1]))

            # Choose the path with maximum sum; if ties, choose the longer path
            if current_paths:
                max_path_sum, max_len = max(current_paths, key=lambda x: (x[0], -x[1]))
                # Handle ties where the longer path is chosen due to path_length priority
                for candidate_sum, candidate_len in current_paths:
                    if candidate_sum == max_path_sum:
                        if candidate_len > max_len:
                            max_path_sum, max_len = candidate_sum, candidate_len
            else:
                continue  # should not happen since (n-1,n-1) is reachable

            # Update max_sum and path_length
            new_val = max_path_sum + cost[i][j]
            max_sum[i][j] = new_val
            path_length[i][j] = max_len + 1

    max_sum_bottom_right = max_sum[-1][-1]
    max_path_length_bottom_right = path_length[-1][-1]
    return max_sum_bottom_right / max_path_length_bottom_right

