    len_dp = [[0] * n for _ in range(n)]

    # Initialize starting position
    sum_dp[0][0] = cost[0][0]
    len_dp[0][0] = 1

    # Fill the first row and first column because it can only be reached one way
    for i in range(1, n):
        sum_dp[i][0] = sum_dp[i-1][0] + cost[i][0]
        len_dp[i][0] = len_dp[i-1][0] + 1

    for j in range(1, n):
        sum_dp[0][j] = sum_dp[0][j-1] + cost[0][j]
