def maxAverageOfPath(cost):
    N = len(cost)
    # dp[i][j] will be a tuple of (total_cost, steps) to reach cell (i, j)
    dp = [[(0, 1) for _ in range(N)] for __ in range(N)]
    dp[0][0] = (cost[0][0], 1)

    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            total, steps = cost[i][j], 1
            options = []
            if i > 0:
                options.append(dp[i-1][j])
            if j > 0:
                options.append(dp[i][j-1])
            for (t, s) in options:
                if t + cost[i][j] > total:
                    total, steps = t + cost[i][j], s + 1
                elif t + cost[i][j] == total and s + 1 > steps:
                    steps = s + 1
            dp[i][j] = (total, steps)

    max_avg = 0.0
    max_total = 0
    max_steps = 0
    for i in range(N):
        for j in range(N):
            total, steps = dp[i][j]
            avg = total / steps
            if avg > max_avg or (avg == max_avg and steps > max_steps):
                max_avg = avg
                max_total = total
                max_steps = steps

    return max_avg

